import { Stage } from "../Stage"

export default class extends Stage {
    protected *G(): Generator<void, void, unknown> {
        yield* this.wait(30)

        yield* this.text(`「明日、避難民代表と土着派、両方と話をつける。」`, { name: "アオ" })
        yield* this.text(`「護衛は最小限でいい。大勢で行ったら、話がこじれる。」`, { name: "アオ" })

        yield* this.text(`「一人で行くようなもんだろ、それ。」`, { name: "テル" })
        yield* this.text(`「あたしがまとめなきゃ、誰がまとめるの。」`, { name: "アオ" })

        yield* this.text(`「あたしも行く。」`, { name: "シオン" })
        yield* this.text(`「駄目。あんたが顔を出したら、余計にこじれる。」`, { name: "アオ" })

        yield* this.text(`昨日の女性の言葉が、シオンの中でまだ棘のように残っていた。<br>それでも、言い返せなかった。`)

        yield* this.text(`「……分かった。」`, { name: "シオン" })
        yield* this.text(`「その代わり、あんたには別件を頼む。国境沿いの哨戒、手薄になってる。」`, { name: "アオ" })

        yield* this.text(`「戻ったら、ちゃんと話聞かせてよ。」`, { name: "シオン" })
        yield* this.text(`「約束する。」`, { name: "アオ" })
    }
}
